import { Table, StringColumn, BooleanColumn, ListColumn } from '../../db'

export const sys_ws_definition = Table({
    allowWebServiceAccess: true,
    attributes: {
        'all_tables.text_index_translations': true,
        update_synch: true,
    },
    display: 'name',
    extends: 'sys_metadata',
    label: 'Scripted REST API',
    name: 'sys_ws_definition',
    schema: {
        base_uri: StringColumn({
            attributes: {
                edge_encryption_enabled: true,
            },
            dynamicValueDefinitions: {
                type: 'calculated_value',
                calculatedValue: `if (current.service_id)
	current.base_uri = '/api/' + current.namespace + '/' + current.service_id;`,
            },
            label: [
                {
                    hint: 'The base API path (URI) to access this API',
                    label: 'Base API path',
                    plural: 'Base APIs paths',
                },
            ],
            maxLength: 255,
            readOnly: true,
            readOnlyOption: 'instance_configured',
        }),
        short_description: StringColumn({
            attributes: {
                edge_encryption_enabled: true,
            },
            label: [
                {
                    hint: 'The description of the API. Appears in API documentation.',
                    label: 'Short description',
                    plural: 'Short descriptions',
                },
            ],
            maxLength: 80,
        }),
        namespace: StringColumn({
            attributes: {
                edge_encryption_enabled: true,
            },
            default: 'javascript:( new ScriptedRESTAPINamespaceCreator().getNamespace())',
            label: [
                {
                    hint: 'The namespace the API belongs to. The value depends on the current application scope.',
                    label: 'API namespace',
                    plural: 'API namespaces',
                },
            ],
            mandatory: true,
            readOnly: true,
            readOnlyOption: 'instance_configured',
        }),
        doc_link: StringColumn({
            attributes: {
                edge_encryption_enabled: true,
            },
            label: [
                {
                    hint: 'Optionally specify a URL that links to static documentation about the API',
                    label: 'Documentation link',
                    plural: 'Documentation links',
                },
            ],
            maxLength: 160,
        }),

        default_version: StringColumn({
            attributes: {
                edge_encryption_enabled: true,
            },
            dynamicValueDefinitions: {
                type: 'calculated_value',
                calculatedValue: `function getDefaultVersion() {
	var defaultVersion = 'No active default version';
	var gr = new GlideRecord('sys_ws_version');
	gr.addQuery('web_service_definition', current.sys_id);
	gr.addQuery('active', true);
	gr.orderByDesc('version');
	gr.query();
	
	while(gr.next()){
		if(gr.getValue('is_default') == '1'){
			defaultVersion = gr.getValue('version_id');
			break;
		}
	}
	
	return defaultVersion;
}

current.default_version = getDefaultVersion();`,
            },
            label: [
                {
                    hint: "The version used when a request does not specify a version. This is the latest version where 'Active' and 'Is default' are both true.",
                    label: 'Default version',
                    plural: 'Default versions',
                },
            ],
            readOnly: true,
            readOnlyOption: 'instance_configured',
        }),
        service_id: StringColumn({
            attributes: {
                edge_encryption_enabled: true,
            },
            label: [
                {
                    hint: 'The API identifier used to distinguish this API in URI paths. Must be unique within API namespace.',
                    label: 'API ID',
                    plural: 'API IDs',
                },
            ],
            mandatory: true,
        }),
        name: StringColumn({
            attributes: {
                edge_encryption_enabled: true,
            },
            label: [
                {
                    hint: 'The name of the API. Appears in API documentation.',
                    label: 'Name',
                    plural: 'Names',
                },
            ],
            mandatory: true,
        }),
        is_versioned: BooleanColumn({
            label: [
                {
                    hint: 'Indicates whether this API has versioning enabled',
                    label: 'Is versioned',
                    plural: 'Is versioned',
                },
            ],
            maxLength: 30,
            readOnly: true,
            readOnlyOption: 'instance_configured',
        }),
        consumes_customized: BooleanColumn({
            default: false,
            label: [
                {
                    hint: 'Check to customize the request media types supported by resources of this API by default',
                    label: 'Override default supported request formats',
                    plural: 'Override default supported request formats',
                },
            ],
            maxLength: 30,
        }),
        active: BooleanColumn({
            default: true,
            label: [
                {
                    hint: 'Activates the API Inactive APIs cannot serve requests.',
                    label: 'Active',
                    plural: 'Active',
                },
            ],
            maxLength: 30,
        }),
        produces_customized: BooleanColumn({
            default: false,
            label: [
                {
                    hint: 'Check to customize the response media types supported by resources of this API by default',
                    label: 'Override default supported response formats',
                    plural: 'Override default supported response formats',
                },
            ],
            maxLength: 30,
        }),
        produces: StringColumn({
            attributes: {
                edge_encryption_enabled: true,
            },
            default: 'application/json,application/xml,text/xml',
            label: [
                {
                    hint: 'Default comma-delimited list of media types that resources of this API can produce',
                    label: 'Default supported response formats',
                    plural: 'Default supported response formats',
                },
            ],
            maxLength: 200,
        }),
        enforce_acl: ListColumn({
            attributes: {
                no_sort: true,
                slushbucket_ref_no_expand: true,
            },
            label: [
                {
                    hint: 'The ACLs to enforce when accessing resources. Individual resources may override this value.',
                    label: 'Default ACLs',
                    plural: 'Default ACLs',
                },
            ],
            maxLength: 16777215,
            referenceTable: 'sys_security_acl',
            referenceQual: 'type=REST_Endpoint^EQ',
            useReferenceQualifier: 'simple',
        }),
        consumes: StringColumn({
            attributes: {
                edge_encryption_enabled: true,
            },
            default: 'application/json,application/xml,text/xml',
            label: [
                {
                    hint: 'Default comma-delimited list of media types that resources of this API can consume',
                    label: 'Default supported request formats',
                    plural: 'Default supported request formats',
                },
            ],
            maxLength: 200,
        }),
    },
    textIndex: true,
})
